+import { describe, it, expect, afterAll, beforeEach } from "vitest";
+import supertest from "supertest";
+import { app, server } from "../../src/index.js";
+import { setAnalysis } from "../../src/routes/analyze.js";
+
+const request = supertest(app);
+
+afterAll(() => {
+  server.close();
+});
